{
  "root_causes": [
    {
      "service": "ts-travel-service",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, attr_span_kind, span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND span_name='POST' GROUP BY 1,2,3", "claim": "Travel-service outgoing POST client spans have p50 about 4.8 s in the abnormal period, versus about 31 ms normal."},
        {"kind": "trace", "sql": "SELECT service_name, attr_span_kind, span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND attr_span_kind='Server' AND span_name LIKE 'POST /api/v1/basicservice/basic/travel%' GROUP BY 1,2,3", "claim": "The called basic-service server spans stay around 57 ms p50, unchanged from normal, so the delay is on the caller side."},
        {"kind": "metric", "sql": "SELECT attr_source, attr_destination, metric, round(avg(value),2) avg_v FROM abnormal_metrics_sum WHERE metric='hubble_drop_total' AND attr_source LIKE '%ts-travel-service%' GROUP BY 1,2,3", "claim": "Hubble drop counters for the travel-service pod are flat (about 2.5 per sample), so no network-level fault is present."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND attr_span_kind='Client' GROUP BY 1,2", "claim": "Travel-service's other outgoing GET calls to route-service stay near normal latency; only the POST path is slow."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-travel-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, attr_span_kind, span_name, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-service','ts-ui-dashboard') AND attr_span_kind='Server' AND span_name LIKE '%trips/left%' OR (service_name='ts-ui-dashboard' AND span_name LIKE '%trips/left%') GROUP BY 1,2,3", "claim": "Travel's trips/left server p95 rises to about 30 s, and ui-dashboard's trips/left spans rise with it."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "Route-plan server spans slow to p95 of about 29 s while calling the slowed travel-service."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "Travel-plan server spans reach p95 of about 17-29 s, consistent with waiting on route-plan."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Client' AND span_name LIKE '%travelPlan%' GROUP BY 1,2", "claim": "Ui-dashboard's calls to travel-plan slow to p95 of about 29 s in the abnormal period."}]},
    {"from": "ts-travel-service", "to": "ts-preserve-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "Preserve server spans slow to p95 of about 11.7 s, driven by its calls to travel-service."}]},
    {"from": "ts-preserve-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Client' AND span_name LIKE '%preserve%' GROUP BY 1,2", "claim": "Ui-dashboard's calls to preserve slow to p95 of about 11.7 s in the abnormal period."}]}
  ]
}
```

